    "description": "当地时间10月2日，印度总理莫迪在社交媒体上发布了一段与受伤的印度籍机长斯米特·马奇切尔的视频连线对话。机长本人描述在千钧一发之际，是如何凭借职业本能与信念应对险情。沙特阿拉伯内政部1日发表声明说，迪拜航空公司客机驾驶舱冲突事件中受伤的机长和副驾驶在沙特接受治疗后，当天在阿联酋安全工作组陪同下离开沙特。",
