    "description": "当地时间2026年10月1日晚，阿塞拜疆首都巴库地标建筑盖达尔·阿利耶夫中心、巴库奥林匹克体育场点亮五星红旗图案，热烈庆祝中华人民共和国成立77周年。 此次亮灯活动充分彰显中阿两国传统友谊，传递阿各界对中国人民的节日祝福，是两国全面战略合作伙伴关系的生动体现。",
