    "title": "1年内在12315平台累计举报1520次，市监部门：具牟利性职业索赔特征",
    "link": "https://m.thepaper.cn/detail/34192197",
    "pub_date": "2026-10-02 18:41:09",
    "author": "“沙坪坝区市场监管”微信公号",
    "description": "“沙坪坝区市场监管”微信公号9月28日发布《沙坪坝区市场监管局公布首批牟利性投诉举报不予受理典型案例》一文，其中包括蔡某某批量投诉终止调解案。文中称，截至2026年9月，蔡某某近一年内在全国12315平台累计发起投诉举报达1520件，其中仅辅助营养补充品类商品投诉举报就达352件，其在短期内高频次就同类问题发起投诉举报的行为模式，已明显超出普通消费者正常维权水平。以下为案例全文。 为依法规制职业索赔职业举报行为，营造良好的营商环境和消费…",
