    "description": "在厦门大学校园里，有国内唯一设在高校的鲁迅纪念馆，其前身为鲁迅在厦大任教时的居所。 1926年9月4日至1927年1月16日，鲁迅在厦门大学任国文系教授与国学院研究教授，除教学之外，还撰写了约17万字的著作，其中就包括《从百草园到三味书屋》《藤野先生》等名篇。 1952年设纪念室以来，该馆历经多次调整布展，现有6个展室：第一展室为“鲁迅生平”，第二展室辟作纪念室，第三展室是“鲁迅与许广平”，第四展室为“鲁迅与厦门大学”，第五展室为“鲁迅…",
    "content": "在厦门大学校园里，有国内唯一设在高校的鲁迅纪念馆，其前身为鲁迅在厦大任教时的居所。 1926年9月4日至1927年1月16日，鲁迅在厦门大学任国文系教授与国学院研究教授，除教学之外，还撰写了约17万字的著作，其中就包括《从百草园到三味书屋》《藤野先生》等名篇。 1952年设纪念室以来，该馆历经多次调整布展，现有6个展室：第一展室为“鲁迅生平”，第二展室辟作纪念室，第三展室是“鲁迅与许广平”，第四展室为“鲁迅与厦门大学”，第五展室为“鲁迅故居”，室内摆设按鲁迅当年居住时的原貌布置，第六展室为资料室，收藏鲁迅著作及相关…"
