    "description": "据新华社消息，2026年10月3日，年度最大下弦月将现身夜空，上演“半个月亮爬上来”的浪漫景致。天文科普专家介绍，2026年全年一共出现13次下弦月。全年最小下弦月则出现在3月11日。",
    "content": "据新华社消息，2026年10月3日，年度最大下弦月将现身夜空，上演“半个月亮爬上来”的浪漫景致。天文科普专家介绍，2026年全年一共出现13次下弦月。全年最小下弦月则出现在3月11日。"
