    "content": "新华社日本名古屋10月2日电（记者黄昕欣、于洋）2日进行的爱知·名古屋亚运会射箭项目比赛中，李梦麒、朱静怡为中国队首夺亚运会射箭反曲弓混合团体项目金牌，并由此获得2028年洛杉矶奥运会席位。赛后，李梦麒表示，这一里程碑表明中国射箭正在往好的方向前进。 10月2日，中国队选手李梦麒（右）、朱静怡在获胜后庆祝。新华社记者 于洋 摄 决赛中，中国队开局顺利，首局李梦麒、朱静怡四箭射下38环，以38:34先下一城，取得两个局分。第二局，中国队以37:35再胜，将总局分优势扩大至4:0。背水一战的印度队在第三局扳回两个局分。…"
