    "description": "新华社北京10月2日电 题：文脉赓续 华章日新——国庆假期里的文化图景 新华社记者 金秋十月，假日中国处处涌动文化热潮。人们走进红色场馆，在凝望中感悟信仰力量；走向乡村沃野，在欢歌里品味丰收喜悦；驻足城市街巷，看老手艺焕发新生。传统与时代相遇，历史与当下交融。 厚植家国情怀 五四大街29号，北大红楼披着晨光，静静矗立。 10月1日，近40组家庭早早聚在北大红楼前。国歌奏响，五星红旗缓缓升起，孩子们挺直腰板，昂首仰望。 “爱国情怀、家国意…",
    "content": "新华社北京10月2日电 题：文脉赓续 华章日新——国庆假期里的文化图景 新华社记者 金秋十月，假日中国处处涌动文化热潮。人们走进红色场馆，在凝望中感悟信仰力量；走向乡村沃野，在欢歌里品味丰收喜悦；驻足城市街巷，看老手艺焕发新生。传统与时代相遇，历史与当下交融。 厚植家国情怀 五四大街29号，北大红楼披着晨光，静静矗立。 10月1日，近40组家庭早早聚在北大红楼前。国歌奏响，五星红旗缓缓升起，孩子们挺直腰板，昂首仰望。 “爱国情怀、家国意识，要从小扎根。”中国共产党早期北京革命活动纪念馆馆长都斌说，北大红楼是马克思主…"
