    "content": "新华社日本名古屋10月2日电（记者孙哲）在2日进行的爱知·名古屋亚运会女子沙滩排球决赛中，中国组合夏欣怡/严旭以1:2不敌泰国组合那拉蓬拉巴/功朴沙鲁达瓦迪，获得银牌。 比赛开始后，夏欣怡/严旭在进攻端始终受到限制，首局17:21落败。第二局，两人及时调整状态，在拦网和发球环节加强施压，逐渐打开局面，以21:13扳回一城。 决胜局，夏欣怡/严旭未能延续冲击力，在部分球的处理上出现失误，面对对手的高拦网，进攻端也出现犹豫，最终以8:15落败。 中国队此前在该项目实现六连冠。已是第四次参加亚运会的夏欣怡，曾搭档不同选手…"
