    "title": "亚运会丨Faker未登场 韩国队卫冕电竞英雄联盟项目",
    "link": "http://www.news.cn/20261002/6e647f0b7c604727b383562095cd94ba/c.html",
    "pub_date": "2026-10-02 16:23:37",
    "author": "郁思辉,许仕豪,肖亚卓,岳晨星",
    "description": "新华社日本名古屋10月2日电（记者郁思辉 许仕豪）在2日进行的爱知·名古屋亚运会电子竞技英雄联盟项目决赛中，韩国队3:0战胜中国台北队，成功卫冕。韩国队传奇选手李相赫（ID:Faker）在比赛中担任替补，并未出场。 韩国队的参赛阵容堪称豪华，全部成员均获得过英雄联盟全球总决赛冠军。这场比赛也是杭州亚运会该项目决赛的“重演”，当时韩国队曾以2:0击败中国台北队。 比赛原定于中午12时开始，但由于现场出现技术故障，开赛时间推迟了约40分钟。…",
    "content": "新华社日本名古屋10月2日电（记者郁思辉 许仕豪）在2日进行的爱知·名古屋亚运会电子竞技英雄联盟项目决赛中，韩国队3:0战胜中国台北队，成功卫冕。韩国队传奇选手李相赫（ID:Faker）在比赛中担任替补，并未出场。 韩国队的参赛阵容堪称豪华，全部成员均获得过英雄联盟全球总决赛冠军。这场比赛也是杭州亚运会该项目决赛的“重演”，当时韩国队曾以2:0击败中国台北队。 比赛原定于中午12时开始，但由于现场出现技术故障，开赛时间推迟了约40分钟。前两局比赛形势如出一辙，中国台北队在前期通过打野和下路的局部联动建立了不小的优势…"
