    "content": "金秋十月，天高云淡，在位于黑龙江省绥化市海伦市的中国科学院海伦农业生态实验站的试验田边，中国科学院东北地理与农业生态研究所寒区大豆育种学科组组长李艳华蹲在地上，捧起一袋新收的大豆摇了摇，听着豆粒哗哗作响，笑着对记者说：“撞击声音发脆的，就是农民期待的好品种。” 在距离实验站不远的海伦市海伦镇护城村大豆科技示范园区里，已是金黄一片，大型收获机车往来穿梭。海伦市农业技术推广中心技术员刘智颖介绍，今年这里种植了1100亩大豆，全部使用“东生”系列品种。有好的品种做基础，加上大垄密植、根瘤菌接种、分层侧深施肥等标准化种植技…"
