    "content": "新华社成都10月2日电（记者赵一帆）“蜀道之难，难于上青天……”国庆期间，四川广元剑门关高铁站的站前广场，许多游客没有急着赶往景区，反而排起了长队，大声背诵着《蜀道难》，场面十分热闹。 剑门关景区。新华社发 “我顺利背完了全文，可以免门票游景区。”来自河北石家庄的游客赵嘉琦兴奋地说，《蜀道难》是她高中最喜欢的课文，这次专程来到广元，想去走完剑门关景区的鸟道和猿猱道，感受诗中“难于上青天”的场景。 剑门关是古蜀道的重要关隘，无数文人墨客穿行于此，留下众多诗篇。李白的《蜀道难》更是写尽了蜀道之艰险奇绝。这个假期，不少游…"
