    "content": "中国国家版本馆中央总馆近日举办“文瀚雅集”活动，邀请文化界专家学者与资深藏家，以版本为媒，解码传统节俗文化。 此次活动展示的珍贵文献与民俗藏品中，既有中国国家版本馆存藏典籍，也有荣宝斋和民间藏家的珍藏。其中，明代刻本《东京梦华录》记载了宋代开封中秋佳节盛况，清光绪三十二年的《燕京岁时记》记录了清代北京地区节令习俗、市井活动与宫廷礼仪。 清代版本《燕京岁时记》。（中国国家版本馆供图） 大家在交流中认为，中秋等传统节日蕴含了丰富的文化内涵，应更好利用现代技术让文献版本“活”起来，弘扬传统文化中蕴含的思想价值。 中国国家…"
