    "content": "新华社日本名古屋10月2日电（记者杨帆）2日，爱知·名古屋亚运会拳击项目迎来决赛日。女子51公斤级率先产生拳击项目首枚金牌，中国队名将、卫冕冠军吴愉凭借强大实力稳稳夺冠。 10月2日，中国选手吴愉在获胜后。新华社记者 陈泽国 摄 当天决赛，吴愉攻防俱佳，将比赛变成“一边倒”的局面，最终以5:0完胜越南选手阮氏心。面对吴愉高质量的防守反击以及灵活游走，阮氏心没有太多办法。五位裁判中，有四位在三个回合均给出吴愉胜出的打分。 赛后说起在国庆节期间夺金，她喜上眉梢：“这几天我在社交媒体上看到，很多中国代表团的运动员在发拿着…"
