    "description": "新华社亚的斯亚贝巴10月2日电（记者刘方强）非洲联盟委员会1日呼吁埃塞俄比亚、厄立特里亚和埃及保持最大限度克制，避免采取可能加剧紧张局势或损害地区和平稳定的行动和言论。 非盟委员会当天发表声明，敦促三国通过现有外交渠道与和平对话方式解决分歧，并表示“非盟已准备好与相关国家协商，支持推动局势降温、对话以及和平解决分歧的努力”。 近期，“提格雷人民解放阵线”武装与埃塞政府军在该国北部地区发生冲突。埃塞方面指责厄立特里亚支持在埃塞北部与政府军…",
    "content": "新华社亚的斯亚贝巴10月2日电（记者刘方强）非洲联盟委员会1日呼吁埃塞俄比亚、厄立特里亚和埃及保持最大限度克制，避免采取可能加剧紧张局势或损害地区和平稳定的行动和言论。 非盟委员会当天发表声明，敦促三国通过现有外交渠道与和平对话方式解决分歧，并表示“非盟已准备好与相关国家协商，支持推动局势降温、对话以及和平解决分歧的努力”。 近期，“提格雷人民解放阵线”武装与埃塞政府军在该国北部地区发生冲突。埃塞方面指责厄立特里亚支持在埃塞北部与政府军作战的武装团体。1日，埃塞外交部发布声明，宣布关闭其在厄首都阿斯马拉的大使馆，并…"
