    "content": "新华社维也纳10月2日电（记者刘海燕）今年是全球发展倡议提出5周年。总部位于奥地利首都维也纳的天邻智库首席执行官常启德日前表示，全球发展倡议直面全球发展赤字，为重振国际发展合作注入关键动能，为推进联合国2030年可持续发展议程提供有力抓手。 常启德曾任联合国发展系统驻华协调员、驻肯尼亚协调员。他在维也纳接受新华社记者采访时说，全球发展倡议直面时代问题，把发展重新置于国际合作的核心位置，这一理念，他既在非洲乡村、也在中国的政策实践中亲眼见证其“落地生根”。 常启德表示，他曾长期在肯尼亚工作，亲眼看到洁净的饮用水、基层…"
