    "description": "新华社东京10月2日电 据日本媒体2日报道，超期服役的日本“隼鸟2”号小行星探测器最后一台正常工作的发动机目前也出现故障。日本宇宙航空研究开发机构准备使用“交叉运行”的方法，使探测器能继续执行任务。 日本共同社2日援引日本宇宙航空研究开发机构的消息报道说，“隼鸟2”号搭载有4台离子发动机，此前已经有3台发生故障，仅剩1台正常运转，而这台B发动机也在今年8月中旬出现状况。该机构尝试恢复，但发动机无法启动。 离子发动机主要由离子推进器与中和…",
    "content": "新华社东京10月2日电 据日本媒体2日报道，超期服役的日本“隼鸟2”号小行星探测器最后一台正常工作的发动机目前也出现故障。日本宇宙航空研究开发机构准备使用“交叉运行”的方法，使探测器能继续执行任务。 日本共同社2日援引日本宇宙航空研究开发机构的消息报道说，“隼鸟2”号搭载有4台离子发动机，此前已经有3台发生故障，仅剩1台正常运转，而这台B发动机也在今年8月中旬出现状况。该机构尝试恢复，但发动机无法启动。 离子发动机主要由离子推进器与中和器两个部分构成，只有两者同时工作，才能正常驱动探测器航行。 据日本时事社报道，日…"
