    "category": "新闻",
    "title": "我国最长海底公路隧道完成盾构掘进",
    "link": "http://www.news.cn/20261002/34957da1352e48839f002325dc346e1f/c.html",
    "pub_date": "2026-10-02 11:55:41",
    "author": "樊曦",
