    "content": "新华社北京10月2日电（记者刘开雄）国家外汇管理局发布的《2026年上半年中国国际收支报告》显示，2026年上半年，外商股权性质直接投资为638亿美元，同比增长55%。 报告显示，外商股权性质直接投资中，反映长期投资意愿的资本金净增加431亿美元；外资企业在境内的收益再投资同比增长31%，表明外资企业将经营所得更多用于在华投资兴业。 分部门看，非金融部门和金融部门吸收外商股权性质直接投资分别为578亿美元和60亿美元。高技术服务业和高技术制造业新增资本金同比增长61%，占非金融部门总体新增资本金的36%，较去年同期…"
