    "content": "新华社北京10月2日电（记者魏玉坤）国家发展改革委民营局日前联合投资司、产业司、高技术司召开有关民营企业和行业协会座谈会，听取在投资过程中存在的问题障碍及意见建议，继续向民营企业推介一批制造业领域投资项目，积极吸引民营企业参与。 本次共推介项目52个，涉及化学原料及化学制品、非金属矿物制品、金属制品、通用设备、专用设备等制造业类型，预计总投资524亿元，拟引入民间资本155亿元，支持民营企业通过独资、控股、参股项目公司等多种方式参与。 据悉，下一步，国家发展改革委将健全常态化向民间资本推介项目机制，继续分批次、小规…"
