    "author": "魏婧宇",
    "description": "新华社呼和浩特10月2日电（记者魏婧宇）国庆假期，内蒙古呼和浩特市的许多烧麦馆里坐满了天南海北的游客。一笼烧麦、一壶砖茶，成为游客感受呼和浩特城市魅力的窗口。 在呼和浩特市回民区的一家烧麦馆中，梁佳欣和父亲这几天格外忙碌。捣皮子、调馅心，梁佳欣将学校学到的烧麦制作技艺搬进厨房，和父亲一同制作传统羊肉烧麦。 梁佳欣是呼和浩特市商贸旅游职业学校烧麦产业学院的毕业生，系统学习了烧麦的传统制作技艺。“我爸爸开了十几年烧麦馆，以前用的烧麦皮都是机…",
    "content": "新华社呼和浩特10月2日电（记者魏婧宇）国庆假期，内蒙古呼和浩特市的许多烧麦馆里坐满了天南海北的游客。一笼烧麦、一壶砖茶，成为游客感受呼和浩特城市魅力的窗口。 在呼和浩特市回民区的一家烧麦馆中，梁佳欣和父亲这几天格外忙碌。捣皮子、调馅心，梁佳欣将学校学到的烧麦制作技艺搬进厨房，和父亲一同制作传统羊肉烧麦。 梁佳欣是呼和浩特市商贸旅游职业学校烧麦产业学院的毕业生，系统学习了烧麦的传统制作技艺。“我爸爸开了十几年烧麦馆，以前用的烧麦皮都是机器压的，调的馅里也少了些传统配料。”梁佳欣说，“在课堂上，非遗传承人教我们用烧麦…"
