    "content": "新华社科威特城10月1日电（记者尹炣）联合国也门问题特使汉斯·格伦德贝里10月1日敦促也门胡塞武装停止在该国西南部塔伊兹省的军事攻势。 格伦德贝里当天在社交媒体平台发表声明说，“我对塔伊兹省的事态发展感到担忧，当地战斗已显著加剧”，胡塞武装的军事行动给平民带来严重风险。 格伦德贝里表示，他收到“令人深感不安的有关人员伤亡、基础设施受损和道路封闭的报告”，道路封闭限制了民众撤离受战争影响地区。他还表示，目前正与也门政府和胡塞武装双方保持密切联系，就控制局势并确保平民自由通行等采取紧急措施进行沟通。 当天早些时候，也门…"
